/bin/bash -lc "python3 << 'EOF'
from PIL import Image
import numpy as np
from collections import deque
a = np.array(Image.open('first_frame.png')).astype(int)
r,g,b = a[...,0],a[...,1],a[...,2]
lum=(r+g+b)/3
def comps(mask, minarea=20):
    H,W=mask.shape
    seen=np.zeros_like(mask,bool)
    out=[]
    for y in range(H):
        for x in range(W):
            if mask[y,x] and not seen[y,x]:
                q=deque([(y,x)]); seen[y,x]=1; pts=[]
                while q:
                    cy,cx=q.popleft(); pts.append((cy,cx))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=cy+dy,cx+dx
                            if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=1; q.append((ny,nx))
                if len(pts)>=minarea:
                    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
                    out.append((len(pts),min(xs),min(ys),max(xs),max(ys)))
    return sorted(out)

dark = lum<60
print(\"DARK components (area,x0,y0,x1,y1):\")
for c in comps(dark, 30): print(c)
bright=(r>120)&(g>130)&(b>150)
print(\"BRIGHT components:\")
for c in comps(bright, 30): print(c)
EOF"
